/**
 * 反复调用，保证响应顺序与调用顺序保持一致
 *
 * ### ❓它是如何保证响应顺序和调用顺序保持一致的
 * 将每次调用按调用顺序串联到一个 promise 上，让即使已经 settled 的 promise 也要等待上个 promise settled 后才能拿到结果，下面是将每次调用分解后外部拿到的 promise 的伪代码
 *
 * 第1次调用拿到的 promise：
 *```ts
 * Promise
 *   .resolve()
 *   .then(() => fetchPromise1)
 * ```
 * 第2次调用拿到的 promise：
 * ```ts
 * Promise
 *   .resolve()
 *   .then(() => fetchPromise1)
 *   .then(() => fetchPromise2)
 * ```
 * 第3次调用拿到的 promise：
 * ```ts
 * Promise
 *   .resolve()
 *   .then(() => fetchPromise1)
 *   .then(() => fetchPromise2)
 *   .then(() => fetchPromise3)
 * ```
 * 这样就能保证我们的响应顺序与调用顺序一致了
 * @example
  const safeFetcher = safeQueueRace(() => Promise.resolve(data))

  // promise 的响应顺序一定按照调用顺序响应
  safeFetcher()
  safeFetcher()
 */
export function safeQueueRace(fetcher: any): (...args: any[]) => Promise<any>;
export function useSafeQueueRace(fn: any): (...args: any[]) => Promise<any>;
